import random
from fractions import Fraction


def first_to_appear(a, b):
    """Exact chance that a appears before b, fair coin."""
    states = sorted({x[:k] for x in (a, b) for k in range(len(x))}, key=len)
    idx = {s: i for i, s in enumerate(states)}
    n = len(states)
    rows = [[Fraction(0)] * n for _ in range(n)]
    rhs = [Fraction(0)] * n
    for s in states:
        i = idx[s]
        rows[i][i] += 1
        for c in 'HT':
            t = s + c
            if t.endswith(a):
                rhs[i] += Fraction(1, 2)
            elif not t.endswith(b):
                while t not in idx:
                    t = t[1:]
                rows[i][idx[t]] -= Fraction(1, 2)
    return solve(rows, rhs)[idx['']]


def penney_sim(a, b, trials, seed):
    rng = random.Random(seed)
    wins = 0
    for _ in range(trials):
        s = ''
        while True:
            s += 'H' if rng.random() < 0.5 else 'T'
            if s.endswith(a):
                wins += 1
                break
            if s.endswith(b):
                break
    return wins / trials
